  CS(lt6, lc6, lt7, lc7);
  CS(lt1, lc1, lt2, lc2);
  CS(lt3, lc3, lt4, lc4);
  CS(lt5, lc5, lt6, lc6);
  CS(lt7, lc7, lt8, lc8);
  CS(lt0, lc0, lt1, lc1);
  CS(lt2, lc2, lt3, lc3);
  CS(lt4, lc4, lt5, lc5);
  CS(lt6, lc6, lt7, lc7);
  CS(lt1, lc1, lt2, lc2);
  CS(lt3, lc3, lt4, lc4);
  CS(lt5, lc5, lt6, lc6);
  CS(lt7, lc7, lt8, lc8);
  CS(lt0, lc0, lt1, lc1);
  CS(lt2, lc2, lt3, lc3);
  CS(lt4, lc4, lt5, lc5);
  CS(lt6, lc6, lt7, lc7);
  CS(lt1, lc1, lt2, lc2);
  CS(lt3, lc3, lt4, lc4);
