  inner += tr * lc3.rgb * lc3.a; tr *= 1.0 - lc3.a;
  inner += tr * lc4.rgb * lc4.a; tr *= 1.0 - lc4.a;
  inner += tr * lc5.rgb * lc5.a; tr *= 1.0 - lc5.a;
  inner += tr * lc6.rgb * lc6.a; tr *= 1.0 - lc6.a;
  inner += tr * lc7.rgb * lc7.a; tr *= 1.0 - lc7.a;
